const busqueda = $input.first().json;
const contexto = $('Start').first().json._firstItem;

const empresa = String(
  contexto.empresa || "NO IDENTIFICADO"
).trim();

if (
  !empresa ||
  empresa === "NO IDENTIFICADO" ||
  empresa === "NO ENCONTRADO"
) {
  throw new Error(
    "RHIA INVESTIGADOR: no existe una empresa identificada para investigar."
  );
}

const resultados = Array.isArray(busqueda.results)
  ? busqueda.results
  : [];


// ============================================================
// FUNCIONES GENERALES
// ============================================================

function limpiarTexto(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}

function textoComparable(valor) {
  return limpiarTexto(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}


// ============================================================
// RECUPERAR URL DESDE SEARXNG
// ============================================================

function obtenerUrl(resultado) {

  if (
    typeof resultado.url === "string" &&
    resultado.url.trim()
  ) {
    return resultado.url.trim();
  }

  const parsed = resultado.parsed_url;

  if (
    Array.isArray(parsed) &&
    parsed.length >= 3 &&
    parsed[0] &&
    parsed[1]
  ) {

    const protocolo = String(parsed[0]);
    const dominio = String(parsed[1]);
    const ruta = String(parsed[2] || "");
    const query = String(parsed[4] || "");
    const fragmento = String(parsed[5] || "");

    let url =
      `${protocolo}://${dominio}${ruta}`;

    if (query) {
      url += `?${query}`;
    }

    if (fragmento) {
      url += `#${fragmento}`;
    }

    return url;
  }

  return "";
}


// ============================================================
// EXTRAER DOMINIO
// ============================================================

function obtenerDominio(url) {

  const coincidencia =
    String(url || "").match(
      /^https?:\/\/([^\/?#]+)/i
    );

  if (!coincidencia) {
    return "";
  }

  return coincidencia[1]
    .replace(/^www\./i, "")
    .toLowerCase();
}


// ============================================================
// TOKENS REALES DEL NOMBRE EMPRESARIAL
// ============================================================

function palabrasMarca(nombre) {

  const legales = new Set([
    "sa",
    "sas",
    "s",
    "a",
    "cia",
    "ltda",
    "limitada",
    "inc",
    "llc",
    "plc"
  ]);

  return textoComparable(nombre)
    .split(/[^a-z0-9]+/)
    .filter(
      palabra =>
        palabra.length >= 2 &&
        !legales.has(palabra)
    );
}


// ============================================================
// IDENTIDAD DE LA EMPRESA
// ============================================================

const empresaComparable =
  textoComparable(empresa);

const tokensEmpresa =
  palabrasMarca(empresa);

const empresaCompacta =
  tokensEmpresa.join("");


// ============================================================
// PALABRAS IMPORTANTES
// ============================================================

const palabrasContacto = [
  "contacto",
  "contact",
  "telefono",
  "teléfono",
  "phone",
  "celular",
  "movil",
  "móvil",
  "whatsapp",
  "correo",
  "email",
  "e-mail",
  "dirección",
  "direccion",
  "directorio"
];

const palabrasPersonas = [
  "linkedin",
  "talento humano",
  "recursos humanos",
  "rrhh",
  "human resources",
  "gerente",
  "director",
  "jefe",
  "coordinador",
  "analista",
  "asistente",
  "administracion",
  "administración",
  "recepcion",
  "recepción"
];

const dominiosSociales = [
  "linkedin.com",
  "facebook.com",
  "instagram.com",
  "x.com",
  "twitter.com"
];

const dominiosDirectorios = [
  "google.com",
  "maps.google",
  "paginasamarillas",
  "yellowpages",
  "zoominfo",
  "apollo",
  "crunchbase"
];


// ============================================================
// ANALIZAR RESULTADOS
// ============================================================

const procesados = [];

for (const resultado of resultados) {

  const titulo =
    limpiarTexto(resultado.title);

  const contenido =
    limpiarTexto(resultado.content);

  const url =
    obtenerUrl(resultado);

  const dominio =
    obtenerDominio(url);

  const engine =
    limpiarTexto(resultado.engine);

  if (!url || !dominio) {
    continue;
  }

  const combinado =
    textoComparable(
      `${titulo} ${contenido} ${url}`
    );

  const dominioComparable =
    textoComparable(dominio)
      .replace(/[^a-z0-9]/g, "");

  let puntuacion = 0;
  const razones = [];

  let dominioEmpresaExacto = false;
  let dominioEmpresaFuerte = false;


  // ==========================================================
  // 1. NOMBRE COMPLETO DE EMPRESA EN RESULTADO
  // ==========================================================

  if (
    empresaComparable &&
    combinado.includes(empresaComparable)
  ) {
    puntuacion += 50;
    razones.push("NOMBRE_EMPRESA");
  }


  // ==========================================================
  // 2. COINCIDENCIA DE PALABRAS DEL NOMBRE
  // ==========================================================

  const tokensCoincidentes =
    tokensEmpresa.filter(
      token =>
        combinado.includes(token)
    );

  if (tokensEmpresa.length > 0) {

    const proporcion =
      tokensCoincidentes.length /
      tokensEmpresa.length;

    if (proporcion === 1) {

      puntuacion += 40;

      razones.push(
        "COINCIDENCIA_COMPLETA_EMPRESA"
      );

    } else if (proporcion >= 0.75) {

      puntuacion += 30;

      razones.push(
        "ALTA_COINCIDENCIA_EMPRESA"
      );

    } else if (proporcion >= 0.5) {

      puntuacion += 15;

      razones.push(
        "COINCIDENCIA_PARCIAL_EMPRESA"
      );
    }
  }


  // ==========================================================
  // 3. DOMINIO CON NOMBRE COMPLETO DE LA EMPRESA
  //
  // Corporación Favorita
  // → corporacionfavorita
  // → corporacionfavorita.com
  //
  // PRIORIDAD MUY ALTA
  // ==========================================================

  if (
    empresaCompacta.length >= 5 &&
    dominioComparable.includes(
      empresaCompacta
    )
  ) {

    puntuacion += 180;

    dominioEmpresaExacto = true;

    razones.push(
      "DOMINIO_EMPRESA_EXACTO"
    );
  }


  // ==========================================================
  // 4. TODOS LOS TOKENS DE LA EMPRESA DENTRO DEL DOMINIO
  // ==========================================================

  const tokensEnDominio =
    tokensEmpresa.filter(
      token =>
        dominioComparable.includes(token)
    );

  if (
    !dominioEmpresaExacto &&
    tokensEmpresa.length >= 2 &&
    tokensEnDominio.length ===
      tokensEmpresa.length
  ) {

    puntuacion += 110;

    dominioEmpresaFuerte = true;

    razones.push(
      "DOMINIO_EMPRESA_FUERTE"
    );
  }


  // ==========================================================
  // 5. SOLO UNA PALABRA DE LA EMPRESA EN EL DOMINIO
  //
  // Ejemplo:
  // Favorita → favoritabananas.com
  //
  // NO debe considerarse automáticamente web oficial.
  // ==========================================================

  if (
    !dominioEmpresaExacto &&
    !dominioEmpresaFuerte &&
    tokensEnDominio.length === 1 &&
    tokensEmpresa.length >= 2
  ) {

    puntuacion += 5;

    razones.push(
      "DOMINIO_COINCIDENCIA_DEBIL"
    );
  }


  // ==========================================================
  // 6. CONTACTO
  // ==========================================================

  const coincidenciasContacto =
    palabrasContacto.filter(
      palabra =>
        combinado.includes(
          textoComparable(palabra)
        )
    );

  if (
    coincidenciasContacto.length > 0
  ) {

    puntuacion += Math.min(
      40,
      coincidenciasContacto.length * 10
    );

    razones.push(
      "POSIBLE_DATO_CONTACTO"
    );
  }


  // ==========================================================
  // 7. PÁGINA ESPECÍFICA DE CONTACTO
  // ==========================================================

  if (
    combinado.includes("contacto") ||
    combinado.includes("contact us") ||
    /\/contact(o)?\/?$/i.test(url)
  ) {

    puntuacion += 35;

    razones.push(
      "PAGINA_CONTACTO"
    );
  }


  // ==========================================================
  // 8. PERSONA / CARGO
  // ==========================================================

  const coincidenciasPersonas =
    palabrasPersonas.filter(
      palabra =>
        combinado.includes(
          textoComparable(palabra)
        )
    );

  if (
    coincidenciasPersonas.length > 0
  ) {

    puntuacion += Math.min(
      30,
      coincidenciasPersonas.length * 6
    );

    razones.push(
      "POSIBLE_PERSONA_CARGO"
    );
  }


  // ==========================================================
  // 9. TIPO DE FUENTE
  // ==========================================================

  let tipoFuente = "WEB";

  if (
    dominiosSociales.some(
      d => dominio.includes(d)
    )
  ) {

    tipoFuente =
      "RED_PROFESIONAL_SOCIAL";

    puntuacion += 5;
  }


  if (
    dominiosDirectorios.some(
      d => dominio.includes(d)
    )
  ) {

    tipoFuente =
      "DIRECTORIO";

    puntuacion += 8;
  }


  if (
    dominioEmpresaExacto ||
    dominioEmpresaFuerte
  ) {

    tipoFuente =
      "POSIBLE_WEB_OFICIAL";
  }


  // ==========================================================
  // 10. PENALIZAR POSIBLES FALSOS POSITIVOS
  // ==========================================================

  if (
    tokensEmpresa.length >= 2 &&
    tokensEnDominio.length === 1 &&
    !combinado.includes(
      empresaComparable
    )
  ) {

    puntuacion -= 30;

    razones.push(
      "POSIBLE_EMPRESA_HOMONIMA"
    );
  }


  // ==========================================================
  // 11. NOTICIAS
  // ==========================================================

  if (
    /\/20\d{2}\//.test(url) ||
    combinado.includes("noticia") ||
    combinado.includes("news")
  ) {

    puntuacion -= 15;

    razones.push(
      "ARTICULO_NOTICIA"
    );
  }


  // ==========================================================
  // GUARDAR RESULTADO
  // ==========================================================

  procesados.push({

    titulo,
    url,
    dominio,
    contenido,
    engine,

    tipo_fuente: tipoFuente,

    puntuacion,

    razones,

    identidad_empresa: {
      dominio_empresa_exacto:
        dominioEmpresaExacto,

      dominio_empresa_fuerte:
        dominioEmpresaFuerte,

      tokens_empresa:
        tokensEmpresa,

      tokens_en_dominio:
        tokensEnDominio
    }
  });
}


// ============================================================
// ELIMINAR DUPLICADOS
// ============================================================

const urlsVistas =
  new Set();

const unicos =
  procesados.filter(resultado => {

    const clave =
      resultado.url
        .replace(/\/$/, "")
        .toLowerCase();

    if (
      urlsVistas.has(clave)
    ) {
      return false;
    }

    urlsVistas.add(clave);

    return true;
  });


// ============================================================
// ORDENAR
// ============================================================

unicos.sort(
  (a, b) =>
    b.puntuacion -
    a.puntuacion
);


// ============================================================
// TOP 12
// ============================================================

const mejores =
  unicos
    .slice(0, 12)
    .map(
      (resultado, indice) => ({

        ranking:
          indice + 1,

        titulo:
          resultado.titulo,

        url:
          resultado.url,

        dominio:
          resultado.dominio,

        contenido:
          resultado.contenido,

        engine:
          resultado.engine,

        tipo_fuente:
          resultado.tipo_fuente,

        puntuacion:
          resultado.puntuacion,

        razones:
          resultado.razones,

        identidad_empresa:
          resultado.identidad_empresa
      })
    );


// ============================================================
// FUENTES CON IDENTIDAD EMPRESARIAL FUERTE
// ============================================================

const fuentesEmpresaVerificada =
  unicos.filter(
    r =>
      r.identidad_empresa
        .dominio_empresa_exacto ||
      r.identidad_empresa
        .dominio_empresa_fuerte
  );


// ============================================================
// SALIDA
// ============================================================

return [
  {
    json: {

      empresa,

      prioridad_investigacion: [
        "WHATSAPP_O_TELEFONO",
        "EMAIL",
        "PERSONA_CONTACTO",
        "CARGO_CONTACTO"
      ],

      datos_comerciales_previos: {

        prioridad_comercial:
          contexto.prioridad_comercial ||
          "NO IDENTIFICADO",

        numero_colaboradores:
          contexto.numero_colaboradores ||
          0,

        rango_empresa:
          contexto.rango_empresa ||
          "NO IDENTIFICADO",

        necesidades_detectadas:
          contexto.necesidades_detectadas ||
          [],

        tipo_negocio:
          contexto.tipo_negocio ||
          "NO IDENTIFICADO",

        sector:
          contexto.sector ||
          "NO IDENTIFICADO",

        pais:
          contexto.pais ||
          "NO IDENTIFICADO",

        ciudad:
          contexto.ciudad ||
          "NO IDENTIFICADO"
      },

      total_resultados_searxng:
        resultados.length,

      total_fuentes_analizadas:
        unicos.length,

      fuentes_identidad_fuerte:
        fuentesEmpresaVerificada.length,

      fuentes_candidatas:
        mejores,

      siguiente_accion:
        fuentesEmpresaVerificada.length > 0
          ? "EXTRAER_Y_VERIFICAR_CONTACTOS"
          : "VERIFICAR_IDENTIDAD_EMPRESA",

      diagnostico:
        null
    }
  }
];

const entrada = $input.first().json;

const empresa = String(
  entrada.empresa || "NO IDENTIFICADO"
).trim();

const fuentes = Array.isArray(entrada.fuentes_candidatas)
  ? entrada.fuentes_candidatas
  : [];


// ============================================================
// 1. FUNCIONES GENERALES
// ============================================================

function limpiarTexto(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizarTexto(valor) {
  return limpiarTexto(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function contextoAlrededor(texto, inicio, fin, margen = 100) {
  const desde = Math.max(0, inicio - margen);
  const hasta = Math.min(texto.length, fin + margen);

  return texto
    .slice(desde, hasta)
    .replace(/\s+/g, " ")
    .trim();
}


// ============================================================
// 2. CONFIANZA DE FUENTE
// ============================================================

function nivelConfianza(fuente) {

  const identidad =
    fuente.identidad_empresa || {};

  if (identidad.dominio_empresa_exacto === true) {
    return "MUY_ALTA";
  }

  if (identidad.dominio_empresa_fuerte === true) {
    return "ALTA";
  }

  const razones = Array.isArray(fuente.razones)
    ? fuente.razones
    : [];

  if (
    razones.includes("NOMBRE_EMPRESA") &&
    razones.includes("COINCIDENCIA_COMPLETA_EMPRESA")
  ) {
    return "MEDIA";
  }

  return "BAJA";
}


// ============================================================
// 3. DETECTAR FUENTES PELIGROSAS / ALERTAS
//
// Evita tomar como teléfono comercial un número que aparezca
// dentro de una alerta de estafa, fraude o suplantación.
// ============================================================

function fuenteConAlerta(fuente) {

  const texto = normalizarTexto(
    `${fuente.titulo || ""} ${fuente.contenido || ""}`
  );

  const alertas = [
    "estafa",
    "estafas",
    "fraude",
    "fraud",
    "phishing",
    "suplantacion",
    "suplantación",
    "alerta de estafas",
    "numero falso",
    "número falso",
    "no corresponde",
    "no pertenece"
  ];

  return alertas.some(
    palabra =>
      texto.includes(normalizarTexto(palabra))
  );
}


// ============================================================
// 4. EXTRAER EMAILS
// ============================================================

function extraerEmails(texto) {

  const regex =
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;

  const encontrados =
    texto.match(regex) || [];

  return [...new Set(
    encontrados.map(
      email =>
        email
          .trim()
          .replace(/[),.;:]+$/g, "")
          .toLowerCase()
    )
  )];
}


// ============================================================
// 5. NORMALIZAR TELÉFONOS
// ============================================================

function normalizarTelefono(valor) {

  let original = String(valor || "").trim();

  const tieneMas =
    original.startsWith("+");

  const digitos =
    original.replace(/\D/g, "");

  if (
    digitos.length < 8 ||
    digitos.length > 15
  ) {
    return null;
  }

  return tieneMas
    ? `+${digitos}`
    : digitos;
}


// ============================================================
// 6. EXTRAER TELÉFONOS / WHATSAPP
//
// Solo aceptamos números cuando alrededor existe una señal
// de contacto: teléfono, celular, WhatsApp, etc.
// ============================================================

function extraerNumeros(texto) {

  const resultados = [];

  const regex =
    /(?:\+?\d[\d\s().-]{6,}\d)/g;

  let match;

  while ((match = regex.exec(texto)) !== null) {

    const numero =
      normalizarTelefono(match[0]);

    if (!numero) {
      continue;
    }

    const contexto =
      contextoAlrededor(
        texto,
        match.index,
        match.index + match[0].length,
        100
      );

    const comparable =
      normalizarTexto(contexto);

    const señalesTelefono = [
      "telefono",
      "teléfono",
      "phone",
      "celular",
      "movil",
      "móvil",
      "contacto",
      "contact",
      "call",
      "llamar",
      "central",
      "oficina",
      "office"
    ];

    const señalesWhatsapp = [
      "whatsapp",
      "wa.me",
      "api.whatsapp.com"
    ];

    const esWhatsapp =
      señalesWhatsapp.some(
        x => comparable.includes(
          normalizarTexto(x)
        )
      );

    const esTelefono =
      señalesTelefono.some(
        x => comparable.includes(
          normalizarTexto(x)
        )
      );

    // Si no hay ninguna señal de contacto,
    // evitamos capturar fechas u otros números.
    if (!esWhatsapp && !esTelefono) {
      continue;
    }

    resultados.push({
      tipo: esWhatsapp
        ? "WHATSAPP"
        : "TELEFONO",
      valor: numero,
      contexto
    });
  }

  return resultados;
}


// ============================================================
// 7. BUSCAR CONTEXTOS CON PERSONAS / CARGOS
//
// Aquí NO inventamos una persona.
// Guardamos fragmentos prometedores para que posteriormente
// Ollama identifique nombre y cargo de forma controlada.
// ============================================================

function encontrarContextosPersona(fuente) {

  const texto =
    limpiarTexto(
      `${fuente.titulo || ""}. ${fuente.contenido || ""}`
    );

  const comparable =
    normalizarTexto(texto);

  const cargos = [
    "gerente",
    "director",
    "directora",
    "jefe",
    "jefa",
    "coordinador",
    "coordinadora",
    "analista",
    "asistente",
    "recursos humanos",
    "talento humano",
    "rrhh",
    "human resources",
    "talent",
    "seleccion",
    "selección",
    "administracion",
    "administración"
  ];

  const encontrados =
    cargos.filter(
      cargo =>
        comparable.includes(
          normalizarTexto(cargo)
        )
    );

  if (encontrados.length === 0) {
    return null;
  }

  return {
    url: fuente.url,
    dominio: fuente.dominio,
    texto,
    palabras_cargo_detectadas:
      encontrados,
    confianza_fuente:
      nivelConfianza(fuente)
  };
}


// ============================================================
// 8. RECORRER FUENTES
// ============================================================

const contactos = [];
const contextosPersonaCargo = [];
const fuentesUtilizadas = [];

for (const fuente of fuentes) {

  const url =
    limpiarTexto(fuente.url);

  if (!url) {
    continue;
  }

  const confianza =
    nivelConfianza(fuente);

  // Ignoramos fuentes de confianza baja para extraer
  // directamente información de contacto.
  if (confianza === "BAJA") {
    continue;
  }

  const alerta =
    fuenteConAlerta(fuente);

  const texto =
    limpiarTexto(
      `${fuente.titulo || ""} ${fuente.contenido || ""}`
    );

  fuentesUtilizadas.push({
    ranking: fuente.ranking,
    url,
    dominio: fuente.dominio,
    confianza,
    alerta
  });


  // ----------------------------------------------------------
  // EMAIL
  // ----------------------------------------------------------

  if (!alerta) {

    const emails =
      extraerEmails(texto);

    for (const email of emails) {

      contactos.push({
        tipo: "EMAIL",
        valor: email,
        fuente: url,
        dominio: fuente.dominio,
        ranking_fuente: fuente.ranking,
        confianza_fuente: confianza
      });
    }


    // --------------------------------------------------------
    // TELÉFONO / WHATSAPP
    // --------------------------------------------------------

    const numeros =
      extraerNumeros(texto);

    for (const numero of numeros) {

      contactos.push({
        tipo: numero.tipo,
        valor: numero.valor,
        fuente: url,
        dominio: fuente.dominio,
        ranking_fuente: fuente.ranking,
        confianza_fuente: confianza,
        contexto: numero.contexto
      });
    }
  }


  // ----------------------------------------------------------
  // POSIBLE PERSONA / CARGO
  // ----------------------------------------------------------

  const contextoPersona =
    encontrarContextosPersona(fuente);

  if (contextoPersona) {
    contextosPersonaCargo.push(
      contextoPersona
    );
  }
}


// ============================================================
// 9. ELIMINAR CONTACTOS DUPLICADOS
// ============================================================

const clavesVistas =
  new Set();

const contactosUnicos =
  contactos.filter(contacto => {

    const clave =
      `${contacto.tipo}|${contacto.valor}`;

    if (clavesVistas.has(clave)) {
      return false;
    }

    clavesVistas.add(clave);

    return true;
  });


// ============================================================
// 10. ORDEN DE CONFIANZA
// ============================================================

const pesoConfianza = {
  MUY_ALTA: 4,
  ALTA: 3,
  MEDIA: 2,
  BAJA: 1
};

contactosUnicos.sort((a, b) => {

  const confianzaA =
    pesoConfianza[a.confianza_fuente] || 0;

  const confianzaB =
    pesoConfianza[b.confianza_fuente] || 0;

  if (confianzaA !== confianzaB) {
    return confianzaB - confianzaA;
  }

  return (
    Number(a.ranking_fuente || 999) -
    Number(b.ranking_fuente || 999)
  );
});


// ============================================================
// 11. SEPARAR CONTACTOS
// ============================================================

const emails =
  contactosUnicos.filter(
    x => x.tipo === "EMAIL"
  );

const whatsapps =
  contactosUnicos.filter(
    x => x.tipo === "WHATSAPP"
  );

const telefonos =
  contactosUnicos.filter(
    x => x.tipo === "TELEFONO"
  );


// ============================================================
// 12. SITIO WEB PROBABLE
// ============================================================

const fuenteOficial =
  fuentes.find(f => {

    const identidad =
      f.identidad_empresa || {};

    return (
      identidad.dominio_empresa_exacto === true ||
      identidad.dominio_empresa_fuerte === true
    );
  });

const sitioWebProbable =
  fuenteOficial
    ? `https://${fuenteOficial.dominio}`
    : "NO IDENTIFICADO";


// ============================================================
// 13. RESUMEN DE CONTACTABILIDAD
// ============================================================

let contactabilidadInvestigada =
  "SIN_CONTACTO";

if (
  emails.length > 0 &&
  (telefonos.length > 0 ||
   whatsapps.length > 0)
) {
  contactabilidadInvestigada =
    "ALTA";

} else if (
  emails.length > 0 ||
  telefonos.length > 0 ||
  whatsapps.length > 0
) {
  contactabilidadInvestigada =
    "MEDIA";
}


// ============================================================
// 14. QUÉ FALTA BUSCAR
// ============================================================

const datosFaltantes = [];

if (whatsapps.length === 0 &&
    telefonos.length === 0) {
  datosFaltantes.push(
    "WHATSAPP_O_TELEFONO"
  );
}

if (emails.length === 0) {
  datosFaltantes.push(
    "EMAIL"
  );
}

// Persona y cargo todavía deben pasar por extracción semántica.
datosFaltantes.push(
  "PERSONA_CONTACTO",
  "CARGO_CONTACTO"
);


// ============================================================
// 15. URLS PRIORITARIAS PARA VERIFICAR DESPUÉS
// ============================================================

const urlsParaVerificar =
  fuentes
    .filter(f => {

      const identidad =
        f.identidad_empresa || {};

      return (
        identidad.dominio_empresa_exacto === true ||
        identidad.dominio_empresa_fuerte === true
      );
    })
    .slice(0, 5)
    .map(f => ({
      url: f.url,
      dominio: f.dominio,
      titulo: f.titulo,
      puntuacion: f.puntuacion
    }));


// ============================================================
// 16. RESULTADO FINAL
// ============================================================

return [
  {
    json: {

      empresa,

      sitio_web_probable:
        sitioWebProbable,

      estado_investigacion:
        "CONTACTOS_EXTRAIDOS_DE_BUSQUEDA",

      prioridad_contacto: [
        "WHATSAPP_O_TELEFONO",
        "EMAIL",
        "PERSONA_CONTACTO",
        "CARGO_CONTACTO"
      ],

      contactabilidad_investigada:
        contactabilidadInvestigada,

      whatsapp_encontrados:
        whatsapps,

      telefonos_encontrados:
        telefonos,

      emails_encontrados:
        emails,

      persona_contacto:
        "NO ENCONTRADO",

      cargo_contacto:
        "NO ENCONTRADO",

      contextos_persona_cargo:
        contextosPersonaCargo.slice(0, 8),

      datos_contacto_faltantes:
        datosFaltantes,

      urls_para_verificar:
        urlsParaVerificar,

      fuentes_utilizadas:
        fuentesUtilizadas,

      siguiente_accion:
        "VERIFICAR_PAGINAS_Y_EXTRAER_PERSONA_CARGO"
    }
  }
];
